"""Install the headless RTC session launcher and its systemd unit."""
module SessionInstall

import ..PipeWireAORTC
using JSON

export install, main

const D = PipeWireAORTC.DeploymentConfiguration
const C = PipeWireAORTC.Common

"Generate a one-shot client launcher bound to the installed application environment."
function installed_launcher(julia::AbstractString; environment::AbstractString)
    return "#!/bin/sh\n" *
           "# Generated by PipeWireAORTC.SessionInstall.install; reinstall to change its environment.\n" *
           "exec $(D.shell_quote(julia)) --startup-file=no --project=" *
           D.shell_quote(environment) *
           " -e 'Base.exit_on_sigint(false); using PipeWireAORTC; exit(PipeWireAORTC.SessionCLI.main(ARGS))' -- \"\$@\"\n"
end

_installed_source_owner(value) =
    throw(ArgumentError("new session install requires a declared held source owner"))
_installed_source_owner(::String) = nothing
_installed_session_cpu(cpu) =
    throw(ArgumentError("RTC CPU placement must exclude CPU 0 and 1"))
_installed_session_cpu(cpu::Int) =
    cpu >= 2 || throw(ArgumentError("RTC CPU placement must exclude CPU 0 and 1"))

function session_spec(package, prefix)
    spec = D.profile(joinpath(package, "deployment.conf"), prefix)
    spec["cpu-latency-us"] === nothing || throw(
        ArgumentError(
            "headless RTC session does not yet retain a CPU DMA latency lease; cpu-latency-us must be null",
        ),
    )
    _installed_source_owner(get(spec, "source-owner", nothing))
    haskey(spec, "node-owners") || throw(
        ArgumentError("new session install requires exact node-owners in deployment.conf"),
    )
    haskey(spec, "session-runtime") ||
        throw(ArgumentError("new session install requires a packaged Julia RTC launcher"))
    placement = spec["placement"]["session"]
    foreach(_installed_session_cpu, placement["cpus"])
    return spec
end

function session_assets(spec, package, prefix)
    PipeWireAORTC.ScienceExport.validate_rtc(joinpath(package, "rtc"))
    binary = D.session_executable(spec, package, prefix)
    isfile(binary) && !islink(binary) && (stat(binary).mode & 0o111) != 0 ||
        throw(ArgumentError("headless RTC Julia launcher is unavailable: $binary"))
    read(binary, String) == PipeWireAORTC.ScienceExport.rtc_launcher() || throw(
        ArgumentError(
            "headless RTC launcher differs from the selected Julia session policy: $binary",
        ),
    )
    return nothing
end

function installed_unit(template, spec; launcher, package, prefix, executable)
    quote_unit(value) = String(JSON.json(replace(String(value), "%" => "%%")))
    leader = spec["placement"]["session"]["leader-cpu"]
    unit = replace(
        template,
        "@LAUNCHER@" => quote_unit(launcher),
        "@PACKAGE@" => quote_unit(package),
        "@PIPEWIRE_PREFIX@" => quote_unit(prefix),
        "@RTC_EXECUTABLE@" => quote_unit(executable),
        "@SOURCE_ROLE@" => spec["source-owner"],
        "@CPUS@" => string(leader),
        "TimeoutStartSec=300" =>
            "TimeoutStartSec=" * string(D.startup_timeout_ms(spec) / 1000),
    )
    occursin(r"@[A-Z_]+@", unit) &&
        throw(ArgumentError("unresolved RTC unit template binding"))
    return unit
end

"""
    install(options)

Validate and copy a sealed session package into a fresh `options.destination`.
Supply absolute `package` and `pipewire_prefix` paths; optional `julia_executable`
selects the Julia client executable. Return the
installation path. Service activation remains a separate operator action.
"""
function install(options)
    source = realpath(options.package)
    prefix = realpath(options.pipewire_prefix)
    source_spec = session_spec(source, prefix)
    haskey(source_spec["artifacts"], "systemd/pipewireao-session@.service") &&
        throw(ArgumentError("export must not seal an installation-specific session unit"))
    session_assets(source_spec, source, prefix)
    executable = D.session_executable(source_spec, abspath(options.destination), prefix)
    julia = D.selected_julia_executable(
        get(options, :julia_executable, Base.julia_cmd().exec[1])
    )
    destination = abspath(options.destination)
    !(ispath(destination) || islink(destination)) ||
        throw(ArgumentError("install destination must be new"))
    # Copy the sealed package without regenerating legacy coordinator units.
    # Rewriting an artifact here would invalidate its retained package hash.
    cp(source, destination; force = false, follow_symlinks = true)
    runtime = PipeWireAORTC.package_root()
    installed_spec = session_spec(destination, prefix)
    session_assets(installed_spec, destination, prefix)
    isfile(executable) && (stat(executable).mode & 0o111) != 0 ||
        throw(ArgumentError("installed RTC Julia launcher is unavailable"))
    bin = joinpath(destination, "bin")
    mkpath(bin)
    launcher = joinpath(bin, "pipewireao-rtc-session")
    environment = D.application_environment(installed_spec, destination)
    script = installed_launcher(julia; environment)
    if haskey(source_spec["artifacts"], "bin/pipewireao-rtc-session")
        read(launcher, String) == script || throw(
            ArgumentError(
                "sealed session launcher differs from the selected Julia executable"
            ),
        )
    else
        write(launcher, script)
    end
    chmod(launcher, 0o755)
    for owner in installed_spec["owners"]
        config = PipeWireAORTC.OpticalStartup.configuration(destination, owner)
        config === nothing ||
            PipeWireAORTC.OpticalStartup.build!(destination, environment, owner, config, prefix)
    end
    template = read(
        joinpath(runtime, "assets/deployment/pipewireao-session@.service.in"), String
    )
    unit = installed_unit(
        template, installed_spec; launcher, package = destination, prefix, executable
    )
    systemd = joinpath(destination, "systemd")
    mkpath(systemd)
    write(joinpath(systemd, "pipewireao-session@.service"), unit)
    return destination
end

"""
    main(argv=ARGS)

Parse installer arguments and return the installed package path. Required flags
are `--package`, `--destination` and `--pipewire-prefix`; validation errors throw.
"""
function main(argv = ARGS)
    args = C.cli_arguments(
        argv;
        required = ["package", "destination", "pipewire-prefix"],
        allowed = ["julia-executable"],
    )
    return install(args)
end

end # module
